//! `tests/sample-draw-order.test.ts`: 5 tests (the TS has 27 snapshot tests + 3: each snapshot is
//! one entry of `BUILDERS` / `TURNS` below, three seeds each, checked in one test per group), 0 compat calls.
//!
//! The pinned draw order is the TS snapshot `tests/__snapshots__/sample-draw-order.test.ts.snap`,
//! converted mechanically to compact JSON (same keys, same values, `undefined` keys absent), one
//! JSON array of three samples (seeds 1, 2, 3, `lcg_rng(seed)`) per fixture.

use super::helpers::T;
use super::sample_support::*;
use crate::error::DiceError;
use crate::turn::trace::SAMPLER_VERSION;
use serde_json::Value;

/// Every JSON number as an f64, so `7` (parsed) equals `7.0` (dumped).
fn norm(v: Value) -> Value {
    match v {
        Value::Number(n) => Value::from(n.as_f64().unwrap_or(f64::NAN)),
        Value::Array(a) => Value::Array(a.into_iter().map(norm).collect()),
        Value::Object(o) => Value::Object(o.into_iter().map(|(k, x)| (k, norm(x))).collect()),
        other => other,
    }
}

fn expected(json: &str) -> Result<Value, serde_json::Error> {
    Ok(norm(serde_json::from_str(json)?))
}

fn pinned<'a>(table: &'a [(&'a str, &'a str)], name: &str) -> Result<&'a str, DiceError> {
    table
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, j)| *j)
        .ok_or_else(|| DiceError::error(format!("no snapshot for {name}")))
}

#[test]
fn draw_order_is_a_contract_builders() -> T {
    let fixtures = builder_fixtures()?;
    assert_eq!(fixtures.len(), BUILDERS.len());
    for (name, sample) in &fixtures {
        let mut got = Vec::new();
        for seed in [1, 2, 3] {
            got.push(sample(&mut lcg_rng(seed))?);
        }
        assert_eq!(
            Value::Array(got),
            expected(pinned(BUILDERS, name)?)?,
            "{name}: fixed seeds, fixed draws"
        );
    }
    Ok(())
}

#[test]
fn draw_order_is_a_contract_turn_sample() -> T {
    let all = fixtures();
    assert_eq!(all.len(), TURNS.len());
    for (name, build) in &all {
        let mut got = Vec::new();
        for seed in [1, 2, 3] {
            got.push(trace_json(&build()?.sample(&mut lcg_rng(seed))?));
        }
        assert_eq!(
            Value::Array(got),
            expected(pinned(TURNS, name)?)?,
            "{name}: fixed seeds, fixed draws"
        );
    }
    Ok(())
}

#[test]
fn fixtures_has_the_22_turns_and_each_resolves_to_a_pmf() -> T {
    let all = fixtures();
    assert_eq!(all.len(), 22);
    for (name, build) in &all {
        assert!(build()?.pmf()?.mean() > 0.0, "{name}");
    }
    Ok(())
}

fn mean_of(name: &str) -> Result<f64, Box<dyn std::error::Error>> {
    let (_, build) = fixtures()
        .into_iter()
        .find(|(n, _)| *n == name)
        .ok_or("no such fixture")?;
    Ok(build()?.pmf()?.mean())
}

#[test]
fn paralyzed_fixture_auto_crits_the_later_melee_attack() -> T {
    let plain = mean_of("advantage grant until next attack")?;
    assert!(mean_of("paralyzed condition (auto-crit on later melee)")? > plain);
    Ok(())
}

#[test]
fn stamps_the_sampler_version() -> T {
    let (_, build) = fixtures()
        .into_iter()
        .find(|(n, _)| *n == "two attacks + sneak attack")
        .ok_or("no fixture")?;
    assert_eq!(
        build()?.sample(&mut lcg_rng(1))?.sampler_version,
        SAMPLER_VERSION
    );
    Ok(())
}

